import{_ as e,o,c as i,ag as a}from"./chunks/plugin-vue_export-helper.BT7B-090.js";const g=JSON.parse('{"title":"Прочёл книгу Итана Расиела \\"Метод McKinsey: как решить любую проблему\\"","description":"","frontmatter":{"site":"pro","title":"Прочёл книгу Итана Расиела \\"Метод McKinsey: как решить любую проблему\\"","date":"2026-09-22T00:00:00.000Z","source":"https://t.me/jfyi_ps/87","head":[["link",{"rel":"canonical","href":"https://oleg-sidorkin.ru/posts/2026-09-22-prochel-knigu-itana-rasiela-metod-mckinsey-kak"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Прочёл книгу Итана Расиела \\"Метод McKinsey: как решить любую проблему\\""}],["meta",{"property":"og:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"property":"og:url","content":"https://oleg-sidorkin.ru/posts/2026-09-22-prochel-knigu-itana-rasiela-metod-mckinsey-kak"}],["meta",{"property":"og:image","content":"https://oleg-sidorkin.ru/og.png"}],["meta",{"property":"og:site_name","content":"Oleg Sidorkin"}],["meta",{"property":"og:locale","content":"ru_RU"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Прочёл книгу Итана Расиела \\"Метод McKinsey: как решить любую проблему\\""}],["meta",{"name":"twitter:description","content":"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы."}],["meta",{"name":"twitter:image","content":"https://oleg-sidorkin.ru/og.png"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BlogPosting\\",\\"headline\\":\\"Прочёл книгу Итана Расиела \\\\\\"Метод McKinsey: как решить любую проблему\\\\\\"\\",\\"description\\":\\"Олег Сидоркин — инженер: кейсы, системы, аудит зрелости платформы.\\",\\"url\\":\\"https://oleg-sidorkin.ru/posts/2026-09-22-prochel-knigu-itana-rasiela-metod-mckinsey-kak\\",\\"inLanguage\\":\\"ru-RU\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"Oleg Sidorkin\\",\\"alternateName\\":\\"alterfo\\",\\"url\\":\\"https://oleg-sidorkin.ru\\",\\"jobTitle\\":\\"Software Engineer\\",\\"knowsAbout\\":[\\"Music\\",\\"Audio DSP\\",\\"AI\\",\\"RAG\\",\\"Frontend Development\\",\\"Solution Architecture\\"],\\"sameAs\\":[\\"https://github.com/alterfo\\"]},\\"datePublished\\":\\"2026-09-22\\"}"]]},"headers":[],"relativePath":"posts/2026-09-22-prochel-knigu-itana-rasiela-metod-mckinsey-kak.md","filePath":"posts/2026-09-22-prochel-knigu-itana-rasiela-metod-mckinsey-kak.md"}'),n={name:"posts/2026-09-22-prochel-knigu-itana-rasiela-metod-mckinsey-kak.md"};function r(s,t,p,l,c,m){return o(),i("div",null,[...t[0]||(t[0]=[a("<p>Заметочки:</p><ul><li><p>Факты превыше всего. В основе любого анализа лежат проверенные данные. Это снижает риск ошибки.</p></li><li><p>Принцип MECE (Mutually Exclusive, Collectively Exhaustive). Применяется в любых исходящих документах и письмах. Любую проблему необходимо разбить на части так, чтобы они не пересекались и в совокупности не оставляли пробелов.</p></li><li><p>Первоначальная гипотеза. Служит навигатором для сбора фактов и анализа. Формируется с использованием принципа 80/20 - найти 20%, которые создают 80% проблем или вычленить 20% клиентов, приносящих 80% прибыли.</p></li><li><p>Лифт-тест презентации. Все презентации строятся по принципу пирамиды - сначала главный вывод и рекомендации, потом подтверждающие аргументы. Если вы не можете заинтересовать за 30 секунд в лифте, значит вы сами не до конца понимаете проблему. Это требует кристальной ясности мышления.</p></li><li><p>Решение должно быть не только правильным и реализуемым, но и соответствовать внутренней политике организации. Иначе это пустая трата ресурсов.</p></li></ul><p>И всяческие очевидности, вроде &quot;будь честен, скажи что не знаешь или что отвлёкся если это так&quot;, &quot;срывай низко висящие фрукты&quot; и &quot;не продавайте, осведомляйте о своей экспертности&quot; и самое важное &quot;три пункта - идеально, от трех до шести - норма&quot;.</p><p>Поработав по книге над своей проблемой поиска позиционирования в консалтинге, пришёл к такой формулировке:</p><p><em><strong>Помогаю руководителям продуктовых компаний, которые увязли в легаси, с долгим time-to-market, хаосом в процессах, без архитектурной роли. За 4-6 недель провожу аудит архитектуры, делаю прототип ключевого решения и даю план миграции. Результат - скорость релизов, меньше рисков, понятные процессы. Берусь от кода до регламентов.</strong></em></p>",5)])])}const k=e(n,[["render",r]]);export{g as __pageData,k as default};
